<?php
namespace App\Services;
use App\Models\User;
use App\Models\Partner;
use Illuminate\Support\Str;
class ReferralCodeService { private const RESERVED = ['ADMIN','API','AUTH','LOGIN','REGISTER','R','SETTINGS','SUPPORT']; public function ensureFor(User|Partner $source): string { return $source->referral_code ?: $this->assign($source, null); } public function regenerate(User|Partner $source): string { return $this->assign($source, $source->referral_code_normalized); } private function assign(User|Partner $source, ?string $previous): string { $base = preg_replace('/[^A-Z0-9]/', '', Str::upper(Str::ascii(Str::before($source->name, ' ')))) ?: 'JAKAWI'; for ($i = 0; $i < 20; $i++) { $code = $base.($i ? random_int(10, 9999) : ''); if ($code === $previous || in_array($code, self::RESERVED, true) || User::where('referral_code_normalized', $code)->whereKeyNot($source instanceof User ? $source->id : null)->exists() || Partner::where('referral_code_normalized', $code)->whereKeyNot($source instanceof Partner ? $source->id : null)->exists()) continue; $source->forceFill(['referral_code' => $code, 'referral_code_normalized' => $code])->save(); return $code; } throw new \RuntimeException('Could not generate referral code.'); } }
